function extract($, ctx) {
  // Locate the menu region; fall back to whole body if needed
  const $menu = $('body.page-template-default.page > main#content > div.page-content > div.elementor.elementor-412');
  if (!$menu.length) $menu = $('body');

  const items = [];
  const seen = new Set();

  // Each price‑list widget corresponds to a menu section
  $menu.find('.elementor-widget-price-list').each((_, widget) => {
    const $widget = $(widget);

    // Determine the section from the nearest preceding heading widget
    let section = null;
    const $headingWidget = $widget.prevAll('.elementor-widget-heading').first();
    if ($headingWidget.length) {
      const headingText = $headingWidget.find('.elementor-heading-title').text();
      section = cleanText(headingText);
    }

    // Extract each menu item inside the price list
    $widget.find('ul.elementor-price-list > li.elementor-price-list-item').each((_, li) => {
      const $li = $(li);

      // Dish name
      const nameEl = $li.find('.elementor-price-list-title');
      const name = cleanText(nameEl.text());
      if (!name) return; // skip empty names

      // Price (first price shown)
      const priceEl = $li.find('.elementor-price-list-price');
      const price = parsePrice(cleanText(priceEl.text()));

      // Description (optional)
      const descEl = $li.find('.elementor-price-list-description');
      const description = descEl.length ? cleanText(descEl.text()) : null;

      // Dedup exact duplicates (e.g., mobile/desktop copies)
      const key = `${section ?? ''}|${name}|${description ?? ''}|${price ?? ''}`;
      if (seen.has(key)) return;
      seen.add(key);

      items.push({ section, name, description, price });
    });
  });

  return items;
}
